-- 세트 352: 도커 정리와 디스크 사용량 실습: system df, container·image·volume·network prune, 필터로 골라 지우기, 남는 것 확인
-- 정답·해설은 서버만 안다. 실습 문제의 grade_cmd 는 checks 의 조건을 && 로 이은 것과 같다. docs/specs/spec_docker_cleanup_set.md
INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (352, 1, '멈춘 컨테이너만 골라 이름 저장하기', '컨테이너가 세 종류 있습니다. 실행 중인 `r1`, 끝나서 **종료(exited)** 된 컨테이너들, 만들기만 하고 시작하지 않은 `c1` 입니다. **종료된(exited) 컨테이너의 이름만** 한 줄에 하나씩 `/tmp/work/exited.txt` 에 저장하세요.', '`docker ps` 는 기본으로 실행 중인 것만 보여 주니 전부 보는 옵션을 더하고, 상태로 거르는 필터는 `--filter status=상태` 예요. 이름만 뽑는 것은 `--format` 템플릿으로 합니다. `created` 와 `exited` 는 다른 상태예요.', 'docker ps -a --filter status=exited --format ''{{.Names}}'' > /tmp/work/exited.txt
cat /tmp/work/exited.txt

# 필터 값은 running, exited, created ... 중 하나. -a 가 없으면 종료된 것은 안 보인다', '["sh", "-c", "docker rm -f $(docker ps -aq) >/dev/null 2>&1; docker volume rm -f $(docker volume ls -q) >/dev/null 2>&1; docker network prune -f >/dev/null 2>&1; docker rmi -f $(docker images -aq) >/dev/null 2>&1; rm -rf /tmp/work; mkdir -p /tmp/work; docker pull -q alpine >/dev/null 2>&1; docker run -d --name r1 alpine sleep 600 >/dev/null; docker run --name e1 alpine true >/dev/null; docker run --name e2 alpine true >/dev/null; docker create --name c1 alpine >/dev/null; true"]', '["sh", "-c", "( [ \\"$(sort /tmp/work/exited.txt 2>/dev/null | tr ''\\\\n'' '' '')\\" = \\"e1 e2 \\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "exited.txt 에 e1 과 e2 만 있다", "cmd": ["sh", "-c", "[ \\"$(sort /tmp/work/exited.txt 2>/dev/null | tr ''\\\\n'' '' '')\\" = \\"e1 e2 \\" ]"]}]', '[{"title": "Docker 공식 문서: docker system df", "url": "https://docs.docker.com/reference/cli/docker/system/df/"}, {"title": "Docker 공식 문서: 사용하지 않는 도커 객체 정리 (prune)", "url": "https://docs.docker.com/engine/manage-resources/pruning/"}, {"title": "Docker 공식 문서: docker container prune", "url": "https://docs.docker.com/reference/cli/docker/container/prune/"}, {"title": "Docker 공식 문서: docker image prune", "url": "https://docs.docker.com/reference/cli/docker/image/prune/"}, {"title": "Docker 공식 문서: docker volume prune", "url": "https://docs.docker.com/reference/cli/docker/volume/prune/"}, {"title": "Docker 공식 문서: docker network prune", "url": "https://docs.docker.com/reference/cli/docker/network/prune/"}, {"title": "Docker 공식 문서: docker container ls (필터)", "url": "https://docs.docker.com/reference/cli/docker/container/ls/"}]'),
  (352, 2, '용량 요약을 내 형식으로 저장하기 (system df --format)', '실행 중 1개, 종료 2개로 컨테이너가 모두 3개 있습니다. **`docker system df`** 의 요약을 `종류: 개수` 모양으로 한 줄씩 `/tmp/work/df.txt` 에 저장하세요. (예: `Containers: 3`) 용량(크기)은 매번 달라서 개수만 담습니다.', '`docker system df` 도 `--format` 을 받아요. 어떤 항목 이름을 쓸 수 있는지 모르겠다면 `--format ''{{json .}}''` 로 한 줄을 먼저 찍어 보세요. 종류와 개수에 해당하는 항목을 `: ` 로 이어 씁니다.', 'docker system df --format ''{{.Type}}: {{.TotalCount}}'' > /tmp/work/df.txt
cat /tmp/work/df.txt

# 크기(.Size)는 환경마다 달라서 채점하지 않는다. 개수는 정해져 있다', '["sh", "-c", "docker rm -f $(docker ps -aq) >/dev/null 2>&1; docker volume rm -f $(docker volume ls -q) >/dev/null 2>&1; docker network prune -f >/dev/null 2>&1; docker rmi -f $(docker images -aq) >/dev/null 2>&1; rm -rf /tmp/work; mkdir -p /tmp/work; docker pull -q alpine >/dev/null 2>&1; docker run -d --name r1 alpine sleep 600 >/dev/null; docker run --name e1 alpine true >/dev/null; docker run --name e2 alpine true >/dev/null; true"]', '["sh", "-c", "( grep -qx ''Containers: 3'' /tmp/work/df.txt 2>/dev/null ) && ( grep -qx ''Images: 1'' /tmp/work/df.txt 2>/dev/null ) && ( grep -qx ''Local Volumes: 0'' /tmp/work/df.txt 2>/dev/null )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "Containers: 3 줄이 있다", "cmd": ["sh", "-c", "grep -qx ''Containers: 3'' /tmp/work/df.txt 2>/dev/null"]}, {"label": "Images: 1 줄이 있다", "cmd": ["sh", "-c", "grep -qx ''Images: 1'' /tmp/work/df.txt 2>/dev/null"]}, {"label": "Local Volumes: 0 줄이 있다", "cmd": ["sh", "-c", "grep -qx ''Local Volumes: 0'' /tmp/work/df.txt 2>/dev/null"]}]', '[{"title": "Docker 공식 문서: docker system df", "url": "https://docs.docker.com/reference/cli/docker/system/df/"}, {"title": "Docker 공식 문서: 사용하지 않는 도커 객체 정리 (prune)", "url": "https://docs.docker.com/engine/manage-resources/pruning/"}, {"title": "Docker 공식 문서: docker container prune", "url": "https://docs.docker.com/reference/cli/docker/container/prune/"}, {"title": "Docker 공식 문서: docker image prune", "url": "https://docs.docker.com/reference/cli/docker/image/prune/"}, {"title": "Docker 공식 문서: docker volume prune", "url": "https://docs.docker.com/reference/cli/docker/volume/prune/"}, {"title": "Docker 공식 문서: docker network prune", "url": "https://docs.docker.com/reference/cli/docker/network/prune/"}, {"title": "Docker 공식 문서: docker container ls (필터)", "url": "https://docs.docker.com/reference/cli/docker/container/ls/"}]'),
  (352, 3, '멈춘 컨테이너 한꺼번에 정리하기 (container prune)', '실행 중인 `r1` 과 이미 끝난 컨테이너 `e1`, `e2` 가 있습니다. **끝난 컨테이너만 전부** 지우고, 실행 중인 `r1` 은 그대로 두세요. 이름을 하나씩 적지 않고 정리 전용 명령 하나로 합니다.', '`docker container prune` 은 멈춘 컨테이너를 모두 지워요. 지우기 전에 "정말?" 하고 물으니 확인을 건너뛰는 옵션(`-f`)을 쓰거나 `y` 를 입력하세요. 실행 중인 컨테이너는 대상이 아닙니다.', 'docker container prune -f
docker ps -a

# prune 은 멈춘 것만 지운다. 실행 중인 r1 은 남는다', '["sh", "-c", "docker rm -f $(docker ps -aq) >/dev/null 2>&1; docker volume rm -f $(docker volume ls -q) >/dev/null 2>&1; docker network prune -f >/dev/null 2>&1; docker rmi -f $(docker images -aq) >/dev/null 2>&1; rm -rf /tmp/work; mkdir -p /tmp/work; docker pull -q alpine >/dev/null 2>&1; docker run -d --name r1 alpine sleep 600 >/dev/null; docker run --name e1 alpine true >/dev/null; docker run --name e2 alpine true >/dev/null; true"]', '["sh", "-c", "( ! docker inspect e1 >/dev/null 2>&1 ) && ( ! docker inspect e2 >/dev/null 2>&1 ) && ( [ \\"$(docker inspect -f ''{{.State.Running}}'' r1 2>/dev/null)\\" = \\"true\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "e1 이 지워졌다", "cmd": ["sh", "-c", "! docker inspect e1 >/dev/null 2>&1"]}, {"label": "e2 가 지워졌다", "cmd": ["sh", "-c", "! docker inspect e2 >/dev/null 2>&1"]}, {"label": "r1 은 실행 중이다", "cmd": ["sh", "-c", "[ \\"$(docker inspect -f ''{{.State.Running}}'' r1 2>/dev/null)\\" = \\"true\\" ]"]}]', '[{"title": "Docker 공식 문서: docker system df", "url": "https://docs.docker.com/reference/cli/docker/system/df/"}, {"title": "Docker 공식 문서: 사용하지 않는 도커 객체 정리 (prune)", "url": "https://docs.docker.com/engine/manage-resources/pruning/"}, {"title": "Docker 공식 문서: docker container prune", "url": "https://docs.docker.com/reference/cli/docker/container/prune/"}, {"title": "Docker 공식 문서: docker image prune", "url": "https://docs.docker.com/reference/cli/docker/image/prune/"}, {"title": "Docker 공식 문서: docker volume prune", "url": "https://docs.docker.com/reference/cli/docker/volume/prune/"}, {"title": "Docker 공식 문서: docker network prune", "url": "https://docs.docker.com/reference/cli/docker/network/prune/"}, {"title": "Docker 공식 문서: docker container ls (필터)", "url": "https://docs.docker.com/reference/cli/docker/container/ls/"}]'),
  (352, 4, '종료 코드로 골라서 지우기 (rm + filter)', '`ok1` 은 정상 종료(코드 0), `f1`, `f2` 는 오류로 종료(코드 1), `r1` 은 실행 중입니다. **오류로 끝난 `f1`, `f2` 만** 지우고 나머지는 남기세요. prune 은 종료 코드로 거를 수 없으니, 목록을 뽑아 그 결과를 `docker rm` 에 넘기는 방식으로 합니다.', '`docker ps -aq` 는 ID 만 한 줄씩 뽑고, 필터에 `exited=종료코드` 를 줄 수 있어요. 명령을 `$( ... )` 로 감싸면 그 출력이 `docker rm` 의 인자가 됩니다. 먼저 목록만 찍어 보고 지우면 안전해요.', 'docker ps -aq --filter exited=1
docker rm $(docker ps -aq --filter exited=1)
docker ps -a

# 필터로 대상을 좁힌 뒤 rm 에 넘긴다', '["sh", "-c", "docker rm -f $(docker ps -aq) >/dev/null 2>&1; docker volume rm -f $(docker volume ls -q) >/dev/null 2>&1; docker network prune -f >/dev/null 2>&1; docker rmi -f $(docker images -aq) >/dev/null 2>&1; rm -rf /tmp/work; mkdir -p /tmp/work; docker pull -q alpine >/dev/null 2>&1; docker run -d --name r1 alpine sleep 600 >/dev/null; docker run --name ok1 alpine true >/dev/null; docker run --name f1 alpine sh -c ''exit 1'' >/dev/null; docker run --name f2 alpine sh -c ''exit 1'' >/dev/null; true"]', '["sh", "-c", "( ! docker inspect f1 >/dev/null 2>&1 ) && ( ! docker inspect f2 >/dev/null 2>&1 ) && ( docker inspect ok1 >/dev/null 2>&1 ) && ( [ \\"$(docker inspect -f ''{{.State.Running}}'' r1 2>/dev/null)\\" = \\"true\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "f1 이 지워졌다", "cmd": ["sh", "-c", "! docker inspect f1 >/dev/null 2>&1"]}, {"label": "f2 가 지워졌다", "cmd": ["sh", "-c", "! docker inspect f2 >/dev/null 2>&1"]}, {"label": "ok1 은 남아 있다", "cmd": ["sh", "-c", "docker inspect ok1 >/dev/null 2>&1"]}, {"label": "r1 은 실행 중이다", "cmd": ["sh", "-c", "[ \\"$(docker inspect -f ''{{.State.Running}}'' r1 2>/dev/null)\\" = \\"true\\" ]"]}]', '[{"title": "Docker 공식 문서: docker system df", "url": "https://docs.docker.com/reference/cli/docker/system/df/"}, {"title": "Docker 공식 문서: 사용하지 않는 도커 객체 정리 (prune)", "url": "https://docs.docker.com/engine/manage-resources/pruning/"}, {"title": "Docker 공식 문서: docker container prune", "url": "https://docs.docker.com/reference/cli/docker/container/prune/"}, {"title": "Docker 공식 문서: docker image prune", "url": "https://docs.docker.com/reference/cli/docker/image/prune/"}, {"title": "Docker 공식 문서: docker volume prune", "url": "https://docs.docker.com/reference/cli/docker/volume/prune/"}, {"title": "Docker 공식 문서: docker network prune", "url": "https://docs.docker.com/reference/cli/docker/network/prune/"}, {"title": "Docker 공식 문서: docker container ls (필터)", "url": "https://docs.docker.com/reference/cli/docker/container/ls/"}]'),
  (352, 5, '라벨로 범위를 좁혀 prune 하기 (--filter)', '멈춘 컨테이너 `t1`, `t2`(라벨 `tier=tmp`)와 `k1`(라벨 `tier=keep`), 그리고 실행 중인 `r1`(라벨 `tier=tmp`)이 있습니다. **`tier=tmp` 라벨이 붙은 멈춘 컨테이너만** prune 으로 지우고, `k1` 과 `r1` 은 남기세요.', '`docker container prune` 도 `--filter` 를 받아요. 라벨 필터는 `label=키=값` 모양입니다. 필터를 줘도 실행 중인 컨테이너는 prune 대상이 되지 않아요.', 'docker container prune -f --filter label=tier=tmp
docker ps -a --format ''{{.Names}} {{.Status}}''

# 필터가 범위를 줄이고, 실행 중인 r1 은 라벨이 맞아도 안전하다', '["sh", "-c", "docker rm -f $(docker ps -aq) >/dev/null 2>&1; docker volume rm -f $(docker volume ls -q) >/dev/null 2>&1; docker network prune -f >/dev/null 2>&1; docker rmi -f $(docker images -aq) >/dev/null 2>&1; rm -rf /tmp/work; mkdir -p /tmp/work; docker pull -q alpine >/dev/null 2>&1; docker run -d --name r1 --label tier=tmp alpine sleep 600 >/dev/null; docker run --name t1 --label tier=tmp alpine true >/dev/null; docker run --name t2 --label tier=tmp alpine true >/dev/null; docker run --name k1 --label tier=keep alpine true >/dev/null; true"]', '["sh", "-c", "( ! docker inspect t1 >/dev/null 2>&1 ) && ( ! docker inspect t2 >/dev/null 2>&1 ) && ( docker inspect k1 >/dev/null 2>&1 ) && ( [ \\"$(docker inspect -f ''{{.State.Running}}'' r1 2>/dev/null)\\" = \\"true\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "t1 이 지워졌다", "cmd": ["sh", "-c", "! docker inspect t1 >/dev/null 2>&1"]}, {"label": "t2 가 지워졌다", "cmd": ["sh", "-c", "! docker inspect t2 >/dev/null 2>&1"]}, {"label": "k1 은 남아 있다", "cmd": ["sh", "-c", "docker inspect k1 >/dev/null 2>&1"]}, {"label": "r1 은 실행 중이다", "cmd": ["sh", "-c", "[ \\"$(docker inspect -f ''{{.State.Running}}'' r1 2>/dev/null)\\" = \\"true\\" ]"]}]', '[{"title": "Docker 공식 문서: docker system df", "url": "https://docs.docker.com/reference/cli/docker/system/df/"}, {"title": "Docker 공식 문서: 사용하지 않는 도커 객체 정리 (prune)", "url": "https://docs.docker.com/engine/manage-resources/pruning/"}, {"title": "Docker 공식 문서: docker container prune", "url": "https://docs.docker.com/reference/cli/docker/container/prune/"}, {"title": "Docker 공식 문서: docker image prune", "url": "https://docs.docker.com/reference/cli/docker/image/prune/"}, {"title": "Docker 공식 문서: docker volume prune", "url": "https://docs.docker.com/reference/cli/docker/volume/prune/"}, {"title": "Docker 공식 문서: docker network prune", "url": "https://docs.docker.com/reference/cli/docker/network/prune/"}, {"title": "Docker 공식 문서: docker container ls (필터)", "url": "https://docs.docker.com/reference/cli/docker/container/ls/"}]'),
  (352, 6, '같은 태그로 다시 만들면 옛 이미지는', '`app:1` 태그가 붙은 이미지를 가지고 있는데, 내용을 바꿔 **같은 `app:1` 태그로 이미지를 다시 만들었습니다**(`docker build -t app:1 .` 이나 `docker commit` 모두 같아요). 예전에 `app:1` 이었던 이미지는 어떻게 될까요?', '이미지의 진짜 이름은 ID 이고, 태그는 그 ID 에 붙은 이름표예요. 이름표 하나는 이미지 하나만 가리킬 수 있습니다. `docker images` 에서 `<none>` 으로 보이는 이미지를 떠올려 보세요.', NULL, NULL, '[]', 'choice', '["새 이미지가 옛 이미지를 덮어써서 옛 이미지는 바로 사라진다", "태그가 새 이미지로 옮겨 가고, 옛 이미지는 이름표 없는 `<none>` 이미지로 남는다", "옛 이미지에 `app:2` 같은 새 태그가 자동으로 붙어 남는다", "같은 태그가 이미 있어서 도커가 다시 만들기를 거부한다"]', 1, '이름표(태그)는 한 번에 이미지 하나만 가리켜요. 같은 태그로 다시 만들면 태그가 **새 이미지로 옮겨 가고**, 옛 이미지는 이름 없는 `<none>`(dangling) 이미지로 **디스크에 그대로 남습니다.** 이런 이미지는 `docker image prune` 의 대상이고, `docker rmi 이미지ID` 로 하나만 지울 수도 있어요. 반대로 `docker rmi app:1` 은 새 이미지의 태그를 떼는 것이라 헷갈리지 않게 조심하세요.', NULL, NULL, NULL, '[{"title": "Docker 공식 문서: docker system df", "url": "https://docs.docker.com/reference/cli/docker/system/df/"}, {"title": "Docker 공식 문서: 사용하지 않는 도커 객체 정리 (prune)", "url": "https://docs.docker.com/engine/manage-resources/pruning/"}, {"title": "Docker 공식 문서: docker container prune", "url": "https://docs.docker.com/reference/cli/docker/container/prune/"}, {"title": "Docker 공식 문서: docker image prune", "url": "https://docs.docker.com/reference/cli/docker/image/prune/"}, {"title": "Docker 공식 문서: docker volume prune", "url": "https://docs.docker.com/reference/cli/docker/volume/prune/"}, {"title": "Docker 공식 문서: docker network prune", "url": "https://docs.docker.com/reference/cli/docker/network/prune/"}, {"title": "Docker 공식 문서: docker container ls (필터)", "url": "https://docs.docker.com/reference/cli/docker/container/ls/"}]'),
  (352, 7, '이름 없는 이미지만 정리하기 (image prune)', '`app:1` 태그로 이미지를 세 번 다시 만들었더니, 이름 없는 이미지(`<none>`)가 두 개 쌓였습니다. **이름 없는 이미지만** 지우고, 태그가 붙은 `app:1` 과 `alpine` 은 그대로 두세요.', '`docker images` 에서 `<none>` 으로 보이는 것이 대상이에요. 전용 정리 명령은 기본으로 이름 없는 이미지만 지웁니다. 확인은 `docker images --filter dangling=true` 로 해요.', 'docker images --filter dangling=true
docker image prune -f
docker images

# -a 를 붙이면 안 쓰는 태그 이미지까지 지워지니 여기서는 붙이지 않는다', '["sh", "-c", "docker rm -f $(docker ps -aq) >/dev/null 2>&1; docker volume rm -f $(docker volume ls -q) >/dev/null 2>&1; docker network prune -f >/dev/null 2>&1; docker rmi -f $(docker images -aq) >/dev/null 2>&1; rm -rf /tmp/work; mkdir -p /tmp/work; docker pull -q alpine >/dev/null 2>&1; docker run --name mkapp11 alpine sh -c ''echo app:1-1 > /v'' >/dev/null; docker commit mkapp11 app:1 >/dev/null; docker rm mkapp11 >/dev/null; docker run --name mkapp12 alpine sh -c ''echo app:1-2 > /v'' >/dev/null; docker commit mkapp12 app:1 >/dev/null; docker rm mkapp12 >/dev/null; docker run --name mkapp13 alpine sh -c ''echo app:1-3 > /v'' >/dev/null; docker commit mkapp13 app:1 >/dev/null; docker rm mkapp13 >/dev/null; true"]', '["sh", "-c", "( [ -z \\"$(docker images -q -f dangling=true)\\" ] ) && ( docker image inspect app:1 >/dev/null 2>&1 ) && ( docker image inspect alpine >/dev/null 2>&1 )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "이름 없는 이미지가 없다", "cmd": ["sh", "-c", "[ -z \\"$(docker images -q -f dangling=true)\\" ]"]}, {"label": "app:1 이 남아 있다", "cmd": ["sh", "-c", "docker image inspect app:1 >/dev/null 2>&1"]}, {"label": "alpine 이 남아 있다", "cmd": ["sh", "-c", "docker image inspect alpine >/dev/null 2>&1"]}]', '[{"title": "Docker 공식 문서: docker system df", "url": "https://docs.docker.com/reference/cli/docker/system/df/"}, {"title": "Docker 공식 문서: 사용하지 않는 도커 객체 정리 (prune)", "url": "https://docs.docker.com/engine/manage-resources/pruning/"}, {"title": "Docker 공식 문서: docker container prune", "url": "https://docs.docker.com/reference/cli/docker/container/prune/"}, {"title": "Docker 공식 문서: docker image prune", "url": "https://docs.docker.com/reference/cli/docker/image/prune/"}, {"title": "Docker 공식 문서: docker volume prune", "url": "https://docs.docker.com/reference/cli/docker/volume/prune/"}, {"title": "Docker 공식 문서: docker network prune", "url": "https://docs.docker.com/reference/cli/docker/network/prune/"}, {"title": "Docker 공식 문서: docker container ls (필터)", "url": "https://docs.docker.com/reference/cli/docker/container/ls/"}]'),
  (352, 8, '쓰지 않는 이미지 모두 정리하기 (image prune -a)', '이름 없는 이미지 하나, 쓰지 않는 태그 이미지 `app:1`, `app:2`, 그리고 `alpine` 을 쓰는 실행 중 컨테이너 `r1` 이 있습니다. **어느 컨테이너도 쓰지 않는 이미지는 태그가 있어도 모두** 지우세요. 단 `r1` 이 쓰는 `alpine` 은 지워지면 안 됩니다.', '기본 이미지 정리는 이름 없는 것만 지워요. 태그가 붙었어도 쓰이지 않는 이미지까지 지우려면 옵션이 하나 더 필요합니다(`--help` 로 찾아보세요). 컨테이너가 쓰는 이미지는 지우려 해도 남아요.', 'docker image prune -a -f
docker images

# -a: 컨테이너가 하나도 안 쓰는 이미지 전부. r1 이 쓰는 alpine 은 남는다', '["sh", "-c", "docker rm -f $(docker ps -aq) >/dev/null 2>&1; docker volume rm -f $(docker volume ls -q) >/dev/null 2>&1; docker network prune -f >/dev/null 2>&1; docker rmi -f $(docker images -aq) >/dev/null 2>&1; rm -rf /tmp/work; mkdir -p /tmp/work; docker pull -q alpine >/dev/null 2>&1; docker run --name mkapp11 alpine sh -c ''echo app:1-1 > /v'' >/dev/null; docker commit mkapp11 app:1 >/dev/null; docker rm mkapp11 >/dev/null; docker run --name mkapp12 alpine sh -c ''echo app:1-2 > /v'' >/dev/null; docker commit mkapp12 app:1 >/dev/null; docker rm mkapp12 >/dev/null; docker run --name mkapp21 alpine sh -c ''echo app:2-1 > /v'' >/dev/null; docker commit mkapp21 app:2 >/dev/null; docker rm mkapp21 >/dev/null; docker run -d --name r1 alpine sleep 600 >/dev/null; true"]', '["sh", "-c", "( ! docker image inspect app:1 >/dev/null 2>&1 ) && ( ! docker image inspect app:2 >/dev/null 2>&1 ) && ( [ -z \\"$(docker images -q -f dangling=true)\\" ] ) && ( docker image inspect alpine >/dev/null 2>&1 ) && ( [ \\"$(docker inspect -f ''{{.State.Running}}'' r1 2>/dev/null)\\" = \\"true\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "app:1 이 지워졌다", "cmd": ["sh", "-c", "! docker image inspect app:1 >/dev/null 2>&1"]}, {"label": "app:2 가 지워졌다", "cmd": ["sh", "-c", "! docker image inspect app:2 >/dev/null 2>&1"]}, {"label": "이름 없는 이미지가 없다", "cmd": ["sh", "-c", "[ -z \\"$(docker images -q -f dangling=true)\\" ]"]}, {"label": "alpine 이 남아 있다", "cmd": ["sh", "-c", "docker image inspect alpine >/dev/null 2>&1"]}, {"label": "r1 은 실행 중이다", "cmd": ["sh", "-c", "[ \\"$(docker inspect -f ''{{.State.Running}}'' r1 2>/dev/null)\\" = \\"true\\" ]"]}]', '[{"title": "Docker 공식 문서: docker system df", "url": "https://docs.docker.com/reference/cli/docker/system/df/"}, {"title": "Docker 공식 문서: 사용하지 않는 도커 객체 정리 (prune)", "url": "https://docs.docker.com/engine/manage-resources/pruning/"}, {"title": "Docker 공식 문서: docker container prune", "url": "https://docs.docker.com/reference/cli/docker/container/prune/"}, {"title": "Docker 공식 문서: docker image prune", "url": "https://docs.docker.com/reference/cli/docker/image/prune/"}, {"title": "Docker 공식 문서: docker volume prune", "url": "https://docs.docker.com/reference/cli/docker/volume/prune/"}, {"title": "Docker 공식 문서: docker network prune", "url": "https://docs.docker.com/reference/cli/docker/network/prune/"}, {"title": "Docker 공식 문서: docker container ls (필터)", "url": "https://docs.docker.com/reference/cli/docker/container/ls/"}]'),
  (352, 9, '쓰지 않는 볼륨 정리하기 (volume prune)', '볼륨이 네 개 있습니다. `live`(실행 중 `r1` 이 사용), `data2`(멈춘 `u1` 이 사용), 아무도 안 쓰는 이름 있는 볼륨 `data1`, 그리고 이름이 없는(익명) 쓰지 않는 볼륨 하나. **어느 컨테이너도 쓰지 않는 볼륨은 이름이 있어도 모두** 지우고, `live` 와 `data2` 는 남기세요.', '`docker volume prune` 은 쓰이지 않는 볼륨을 지우는데, 도커 버전에 따라 기본값이 익명 볼륨만일 수 있어요. 이름 있는 볼륨까지 지우는 옵션이 있는지 `docker volume prune --help` 로 보세요. 멈춘 컨테이너가 쓰는 볼륨은 "사용 중"입니다.', 'docker volume prune -a -f
docker volume ls

# 컨테이너가(멈춘 것도) 연결한 볼륨은 남는다. data1 과 익명 볼륨만 사라진다', '["sh", "-c", "docker rm -f $(docker ps -aq) >/dev/null 2>&1; docker volume rm -f $(docker volume ls -q) >/dev/null 2>&1; docker network prune -f >/dev/null 2>&1; docker rmi -f $(docker images -aq) >/dev/null 2>&1; rm -rf /tmp/work; mkdir -p /tmp/work; docker pull -q alpine >/dev/null 2>&1; docker volume create data1 >/dev/null; docker run -d --name r1 -v live:/d alpine sleep 600 >/dev/null; docker run --name u1 -v data2:/d alpine true >/dev/null; docker run --name tmpv -v /x alpine true >/dev/null; docker rm tmpv >/dev/null; true"]', '["sh", "-c", "( ! docker volume inspect data1 >/dev/null 2>&1 ) && ( docker volume inspect live >/dev/null 2>&1 ) && ( docker volume inspect data2 >/dev/null 2>&1 ) && ( [ \\"$(docker volume ls -q | wc -l | tr -d '' '')\\" = \\"2\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "data1 이 지워졌다", "cmd": ["sh", "-c", "! docker volume inspect data1 >/dev/null 2>&1"]}, {"label": "live 는 남아 있다", "cmd": ["sh", "-c", "docker volume inspect live >/dev/null 2>&1"]}, {"label": "data2 는 남아 있다", "cmd": ["sh", "-c", "docker volume inspect data2 >/dev/null 2>&1"]}, {"label": "볼륨이 2개만 남았다", "cmd": ["sh", "-c", "[ \\"$(docker volume ls -q | wc -l | tr -d '' '')\\" = \\"2\\" ]"]}]', '[{"title": "Docker 공식 문서: docker system df", "url": "https://docs.docker.com/reference/cli/docker/system/df/"}, {"title": "Docker 공식 문서: 사용하지 않는 도커 객체 정리 (prune)", "url": "https://docs.docker.com/engine/manage-resources/pruning/"}, {"title": "Docker 공식 문서: docker container prune", "url": "https://docs.docker.com/reference/cli/docker/container/prune/"}, {"title": "Docker 공식 문서: docker image prune", "url": "https://docs.docker.com/reference/cli/docker/image/prune/"}, {"title": "Docker 공식 문서: docker volume prune", "url": "https://docs.docker.com/reference/cli/docker/volume/prune/"}, {"title": "Docker 공식 문서: docker network prune", "url": "https://docs.docker.com/reference/cli/docker/network/prune/"}, {"title": "Docker 공식 문서: docker container ls (필터)", "url": "https://docs.docker.com/reference/cli/docker/container/ls/"}]'),
  (352, 10, '쓰지 않는 네트워크 정리하기 (network prune)', '사용자 정의 네트워크 `net-a`, `net-b`, `net-c` 가 있고, 실행 중인 `r1` 이 `net-b` 에 연결돼 있습니다. **아무도 쓰지 않는 네트워크만** 지우세요. 도커가 기본으로 가진 네트워크(`bridge` 등)와 `net-b` 는 남아야 합니다.', '이번에는 네트워크용 정리 명령이에요(`docker network ...`). 연결된 컨테이너가 있는 네트워크와 기본 네트워크는 prune 이 알아서 건드리지 않습니다. 목록은 `docker network ls` 로 봅니다.', 'docker network prune -f
docker network ls

# 연결된 컨테이너가 있는 net-b 와 기본 네트워크는 남는다', '["sh", "-c", "docker rm -f $(docker ps -aq) >/dev/null 2>&1; docker volume rm -f $(docker volume ls -q) >/dev/null 2>&1; docker network prune -f >/dev/null 2>&1; docker rmi -f $(docker images -aq) >/dev/null 2>&1; rm -rf /tmp/work; mkdir -p /tmp/work; docker pull -q alpine >/dev/null 2>&1; docker network create net-a >/dev/null; docker network create net-b >/dev/null; docker network create net-c >/dev/null; docker run -d --name r1 --network net-b alpine sleep 600 >/dev/null; true"]', '["sh", "-c", "( ! docker network inspect net-a >/dev/null 2>&1 ) && ( ! docker network inspect net-c >/dev/null 2>&1 ) && ( docker network inspect net-b >/dev/null 2>&1 ) && ( [ \\"$(docker inspect -f ''{{.State.Running}}'' r1 2>/dev/null)\\" = \\"true\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "net-a 가 지워졌다", "cmd": ["sh", "-c", "! docker network inspect net-a >/dev/null 2>&1"]}, {"label": "net-c 가 지워졌다", "cmd": ["sh", "-c", "! docker network inspect net-c >/dev/null 2>&1"]}, {"label": "net-b 는 남아 있다", "cmd": ["sh", "-c", "docker network inspect net-b >/dev/null 2>&1"]}, {"label": "r1 은 실행 중이다", "cmd": ["sh", "-c", "[ \\"$(docker inspect -f ''{{.State.Running}}'' r1 2>/dev/null)\\" = \\"true\\" ]"]}]', '[{"title": "Docker 공식 문서: docker system df", "url": "https://docs.docker.com/reference/cli/docker/system/df/"}, {"title": "Docker 공식 문서: 사용하지 않는 도커 객체 정리 (prune)", "url": "https://docs.docker.com/engine/manage-resources/pruning/"}, {"title": "Docker 공식 문서: docker container prune", "url": "https://docs.docker.com/reference/cli/docker/container/prune/"}, {"title": "Docker 공식 문서: docker image prune", "url": "https://docs.docker.com/reference/cli/docker/image/prune/"}, {"title": "Docker 공식 문서: docker volume prune", "url": "https://docs.docker.com/reference/cli/docker/volume/prune/"}, {"title": "Docker 공식 문서: docker network prune", "url": "https://docs.docker.com/reference/cli/docker/network/prune/"}, {"title": "Docker 공식 문서: docker container ls (필터)", "url": "https://docs.docker.com/reference/cli/docker/container/ls/"}]'),
  (352, 11, '볼륨까지 한 번에 정리', '쓰지 않는 컨테이너, 네트워크, 이름 없는 이미지를 한 번에 정리하되 **볼륨까지 함께** 지우려고 합니다. 빈칸에 알맞은 옵션을 채우세요.', '`docker system prune` 만 쓰면 볼륨은 지우지 않아요(데이터를 지키려는 안전장치). 볼륨을 대상에 넣는 옵션은 이름 그대로 "볼륨" 이에요. `-a` 는 이미지의 범위를 넓히는 옵션이라 볼륨과는 상관없습니다.', NULL, NULL, '[]', 'fill', '["--volumes", "-a", "--all", "--dangling"]', NULL, '`docker system prune` 은 기본으로 멈춘 컨테이너, 쓰지 않는 네트워크, 이름 없는 이미지만 지우고 **볼륨은 건드리지 않습니다.** `--volumes` 를 더해야 쓰지 않는 볼륨까지 지워져요. `-a`(`--all`)는 태그가 붙은 안 쓰는 이미지까지 넓히는 옵션이고, `--dangling` 은 system prune 의 옵션이 아닙니다. 데이터가 든 볼륨이 날아갈 수 있으니 실제 운영에서는 신중하게 쓰세요.', '[0]', 'docker system prune {0} -f', NULL, '[{"title": "Docker 공식 문서: docker system df", "url": "https://docs.docker.com/reference/cli/docker/system/df/"}, {"title": "Docker 공식 문서: 사용하지 않는 도커 객체 정리 (prune)", "url": "https://docs.docker.com/engine/manage-resources/pruning/"}, {"title": "Docker 공식 문서: docker container prune", "url": "https://docs.docker.com/reference/cli/docker/container/prune/"}, {"title": "Docker 공식 문서: docker image prune", "url": "https://docs.docker.com/reference/cli/docker/image/prune/"}, {"title": "Docker 공식 문서: docker volume prune", "url": "https://docs.docker.com/reference/cli/docker/volume/prune/"}, {"title": "Docker 공식 문서: docker network prune", "url": "https://docs.docker.com/reference/cli/docker/network/prune/"}, {"title": "Docker 공식 문서: docker container ls (필터)", "url": "https://docs.docker.com/reference/cli/docker/container/ls/"}]'),
  (352, 12, '디스크가 찼을 때 정리하는 순서', '디스크가 차서 안 쓰는 것을 정리하려고 합니다. 확인하고 지우고 결과를 보는 흐름을 앞에서 뒤로 놓으세요.', '먼저 어디에 용량을 쓰는지 보고, 지울 대상을 확인한 뒤 지웁니다. 컨테이너가 남아 있으면 그 컨테이너가 쓰는 이미지와 볼륨은 지워지지 않으니 컨테이너부터 치워요. 마지막에 다시 확인합니다.', NULL, NULL, '[]', 'order', '["`docker system df` 로 어디에 용량을 쓰는지 본다", "`docker ps -a --filter status=exited` 로 지울 컨테이너를 먼저 확인한다", "`docker container prune -f` 로 멈춘 컨테이너를 지운다", "`docker image prune -f` 로 이름 없는 이미지를 지운다", "`docker volume prune -f` 로 쓰지 않는 볼륨을 지운다", "`docker system df` 로 용량이 줄었는지 다시 본다"]', NULL, '**df 로 현황 → 대상 확인 → 컨테이너 prune → 이미지 prune → 볼륨 prune → df 로 재확인** 순서입니다. 멈춘 컨테이너가 이미지와 볼륨을 붙잡고 있어서 컨테이너를 먼저 지워야 이미지·볼륨이 풀려요. 지우기 전에 목록으로 확인하는 습관이 사고를 막습니다.', '[0, 1, 2, 3, 4, 5]', NULL, NULL, '[{"title": "Docker 공식 문서: docker system df", "url": "https://docs.docker.com/reference/cli/docker/system/df/"}, {"title": "Docker 공식 문서: 사용하지 않는 도커 객체 정리 (prune)", "url": "https://docs.docker.com/engine/manage-resources/pruning/"}, {"title": "Docker 공식 문서: docker container prune", "url": "https://docs.docker.com/reference/cli/docker/container/prune/"}, {"title": "Docker 공식 문서: docker image prune", "url": "https://docs.docker.com/reference/cli/docker/image/prune/"}, {"title": "Docker 공식 문서: docker volume prune", "url": "https://docs.docker.com/reference/cli/docker/volume/prune/"}, {"title": "Docker 공식 문서: docker network prune", "url": "https://docs.docker.com/reference/cli/docker/network/prune/"}, {"title": "Docker 공식 문서: docker container ls (필터)", "url": "https://docs.docker.com/reference/cli/docker/container/ls/"}]');
